-- Career module PR 2 (spec 2026-10-22 cv-tailoring §6): the owner's CV base, versioned, with at most one
-- pending draft and one active version per user. Additive only: a new table and two new enum types.

-- CreateEnum (generated by `prisma migrate diff`)
CREATE TYPE "cv_draft_status" AS ENUM ('EXTRACTING', 'READY', 'FAILED');

-- CreateEnum
CREATE TYPE "cv_extraction_failure" AS ENUM ('EXTRACTION_FAILED', 'TIMED_OUT');

-- CreateTable
CREATE TABLE "cv_bases" (
    "id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "version" INTEGER NOT NULL,
    "status" "cv_draft_status" NOT NULL,
    "failure_reason" "cv_extraction_failure",
    "content" JSONB,
    "extracted_text" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT false,
    "confirmed_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "cv_bases_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "cv_bases_user_id_version_key" ON "cv_bases"("user_id", "version");

-- AddForeignKey
ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Hand-written invariants (what the Prisma schema cannot express)
-- At most one active version and at most one unconfirmed draft per user.
CREATE UNIQUE INDEX "cv_bases_user_id_active_key" ON "cv_bases"("user_id") WHERE "is_active";
CREATE UNIQUE INDEX "cv_bases_user_id_draft_key" ON "cv_bases"("user_id") WHERE "confirmed_at" IS NULL;

ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_version_check" CHECK ("version" >= 1);
-- Each status carries exactly its own payload: the PDF text only while EXTRACTING, the structured
-- content only when READY, a failure reason only when FAILED.
ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_status_payload_check" CHECK (
  CASE "status"
    WHEN 'EXTRACTING' THEN "extracted_text" IS NOT NULL AND "content" IS NULL AND "failure_reason" IS NULL
    WHEN 'READY' THEN "extracted_text" IS NULL AND "content" IS NOT NULL AND "failure_reason" IS NULL
    WHEN 'FAILED' THEN "extracted_text" IS NULL AND "content" IS NULL AND "failure_reason" IS NOT NULL
  END
);
-- Only a confirmed READY version can be active; confirmation implies READY.
ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_confirmation_check"
  CHECK (("confirmed_at" IS NULL OR "status" = 'READY') AND (NOT "is_active" OR "confirmed_at" IS NOT NULL));
-- Bounds mirror the contract (`CV_UPLOAD_LIMITS.maxTextChars`); content is a JSON object, ≤ 256 KiB.
ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_extracted_text_check"
  CHECK ("extracted_text" IS NULL OR char_length("extracted_text") BETWEEN 1 AND 60000);
ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_content_check"
  CHECK ("content" IS NULL OR (jsonb_typeof("content") = 'object' AND octet_length("content"::text) <= 262144));
